import{z as A,x as B,o as e,c as d,q as r,j as o,D as E,d as t,s as l,S as s,b as i}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"节点命名与实际尺寸","description":"","frontmatter":{"title":"节点命名与实际尺寸","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/node-naming.md","filePath":"litho/node-naming.md","lastUpdated":1791063341000}'),p={name:"litho/node-naming.md"};function m(h,a,P,C,D,c){const n=B("Mermaid");return e(),d("div",null,[a[2]||(a[2]=r('<h1 id="节点命名与实际尺寸" tabindex="-1">节点命名与实际尺寸 <a class="header-anchor" href="#节点命名与实际尺寸" aria-label="Permalink to &quot;节点命名与实际尺寸&quot;">​</a></h1><div class="epigraph"><p>商品名「7 nm」「18A」不是栅长，也不是金属半节距；比较工艺要用 CPP、MMP 和密度，而不是广告数字。</p><footer>—— 对照代工节点命名与实际几何脱节的公开讨论（ISSCC / WikiChip 一类对照传统）</footer></div><p><a href="/litho/failure-analysis-tem-fib">上一课</a>把图形化失效收到 FIB/TEM 剖面，「集成、控制与良率」在那里封口。本课起「路线图、经济与替代」：良率账已经能对到几何，缺口变成节点名是不是物理量。真正该比的格子，留给<a href="/litho/cpp-mmp">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>历史上节点名曾近乎栅长。多重图形与 FinFET 之后，名字变成密度与市场世代的标签：不同厂的「7 nm」鳍节距、金属节距、是否 EUV，都可以不同。光刻代价必须按层类型计，不能按商品名计。<a href="/litho/duv-multipattern-cost">DUV 多重代价</a> 已警告过这一点；本课把它收成路线图语言。</p><p>缺口是<strong>名字不是物理量</strong>，不是再分析一次 TEM。把「我们进了 3 nm」写成 NA 或波长变了，常常只是库与分解变了。</p><p><span class="marginnote">数字感受：商品名叫「7 nm」的工艺，实际栅长通常仍在 20 nm 上下，金属半节距几十纳米——「7」只是世代序号，和任何一张截面上的尺寸都对不上。常见误区：以为「5 nm 比 7 nm 的所有尺寸都小 2 nm」，实际上两家不同代工的「同名节点」连鳍节距是否用 EUV 都可能不同。</span></p><h3 id="本课不重推瑞利" tabindex="-1">本课不重推瑞利 <a class="header-anchor" href="#本课不重推瑞利" aria-label="Permalink to &quot;本课不重推瑞利&quot;">​</a></h3><p>分辨率仍由 \\(λ\\)、NA、\\(k_1\\) 与分解决定。节点名不出现在这些符号里。后课 CPP/MMP 才是可写入公式的量。</p><p><span class="marginnote">比较两家「同名节点」而不列 CPP/MMP/EUV 层数，是市场比较，不是光刻比较。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>阅读路线图与新闻时：把节点名翻译成（公开的）节距、层数、曝光策略。内部 DTCO 用节距，不用名字。IRDS 后课用物理路线，也仍会提到行业世代名——要能翻译。</p>',12)),(e(),o(s,null,{default:E(()=>[l(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20SEE%5B%22%E7%9C%8B%E5%88%B0%E8%8A%82%E7%82%B9%E5%90%8D%20Nnm%20%2F%20XXA%22%5D%20--%3E%20Q1%5B%22%E6%9F%A5%E5%85%AC%E5%BC%80%20CPP%20%E4%B8%8E%20MMP%22%5D%0A%20%20SEE%20--%3E%20Q2%5B%22%E6%9F%A5%20EUV%20%E5%B1%82%E6%95%B0%20%2F%20%E6%9B%9D%E5%85%89%E7%AD%96%E7%95%A5%22%5D%0A%20%20SEE%20--%3E%20Q3%5B%22%E6%9F%A5%E6%99%B6%E4%BD%93%E7%AE%A1%E5%AF%86%E5%BA%A6%20%E5%8F%A3%E5%BE%84%E4%B8%80%E8%87%B4%22%5D%0A%20%20Q1%20--%3E%20T%5B%22%E5%90%8C%E5%B0%BA%E6%AF%94%E8%BE%83%3A%20%E8%8A%82%E8%B7%9D%20%2B%20%E5%B1%82%E6%95%B0%20%2B%20%E5%AF%86%E5%BA%A6%22%5D%0A%20%20Q2%20--%3E%20T%0A%20%20Q3%20--%3E%20T%0A%20%20T%20--%3E%20VER%7B%22%E5%8F%A3%E5%BE%84%E7%9B%B8%E5%90%8C%3F%22%7D%0A%20%20VER%20--%3E%7C%22%E6%98%AF%22%7C%20OK%5B%22%E5%8F%AF%E6%AF%94%22%5D%0A%20%20VER%20--%3E%7C%22%E5%90%A6%22%7C%20NO%5B%22%E5%8F%AA%E6%98%AF%E5%B8%82%E5%9C%BA%E5%AF%B9%E6%AF%94%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=i("h2",{id:"机制",tabindex:"-1"},[t("机制 "),i("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=i("p",null,"命名脱节的原因是：密度可由助推器、轨道高度、EUV 减层共同提高，不必按比例缩所有节距。名字跟世代走，节距跟可印集合走，两条轴。",-1)),(e(),o(s,null,{default:E(()=>[l(n,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20NAME%5B%22%E5%95%86%E5%93%81%E8%8A%82%E7%82%B9%E5%90%8D%22%5D%20--%3E%20MKT%5B%22%E5%B8%82%E5%9C%BA%E4%B8%96%E4%BB%A3%22%5D%0A%20%20PHYS%5B%22CPP%20MMP%20%E5%B1%82%E7%AD%96%E7%95%A5%22%5D%20--%3E%20LITH%5B%22%E5%85%89%E5%88%BB%E4%BB%A3%E4%BB%B7%22%5D%0A%20%20NAME%20-.-%3E%7C%22%E4%B8%8D%E8%83%BD%E7%9B%B4%E6%8E%A5%22%7C%20LITH%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不编造某厂未公开的节距。不贬低工程，只钉语言。本课不列完整对照表（会过时）。</p><p><span class="marginnote">术语翻译：CPP 是「接触栅节距」——单元里相邻两条栅的中心距，决定单元高度；MMP 是「最小金属节距」，决定布线密度；两者才是格子大小的真尺子。直觉类比：节点名像衣服的尺码「均码/加大」，CPP 和 MMP 才是胸围衣长——不同牌子同码衣服大小可以差很多，买之前得量尺寸。</span></p><p>后课默认：讨论尺寸用 CPP/MMP；下一课定义这两根尺子。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>节点名是世代标签，不是栅长或半节距。</li><li>光刻比较必须落到节距与层策略。</li><li>密度可由架构助推，不必与名字成比例。</li><li>出处：IEEE IRDS Lithography（节点名 ≠ 最小半节距）；Moore, <em>Electronics</em> 38(8) (1965)；代工命名与几何脱节的公开对照。</li></ul>',6))])}const T=A(p,[["render",m]]);export{u as __pageData,T as default};
